class Solution {
    public int countCompleteSubarrays(int[] nums) {
        java.util.Set<Integer> allValues = new java.util.HashSet<>();
        for (int value : nums) {
            allValues.add(value);
        }
        int requiredDistinct = allValues.size();

        java.util.Map<Integer, Integer> window = new java.util.HashMap<>();
        int answer = 0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            window.put(nums[right], window.getOrDefault(nums[right], 0) + 1);
            while (window.size() == requiredDistinct) {
                answer += nums.length - right;
                int leaving = nums[left++];
                int nextCount = window.get(leaving) - 1;
                if (nextCount == 0) {
                    window.remove(leaving);
                } else {
                    window.put(leaving, nextCount);
                }
            }
        }
        return answer;
    }
}

class Solution {
    public int countCompleteSubarrays(int[] nums) {
        java.util.Set<Integer> allValues = new java.util.HashSet<>();
        for (int value : nums) {
            allValues.add(value);
        }
        int requiredDistinct = allValues.size();

        int answer = 0;
        for (int left = 0; left < nums.length; left++) {
            java.util.Set<Integer> seen = new java.util.HashSet<>();
            for (int right = left; right < nums.length; right++) {
                seen.add(nums[right]);
                if (seen.size() == requiredDistinct) {
                    answer++;
                }
            }
        }
        return answer;
    }
}

class Solution {
    public int countCompleteSubarrays(int[] nums) {
        boolean[] exists = new boolean[2001];
        int totalDistinct = 0;
        for (int num : nums) {
            if (!exists[num]) {
                exists[num] = true;
                totalDistinct++;
            }
        }

        int[] freq = new int[2001];
        int inside = 0;
        int left = 0;
        int answer = 0;
        for (int right = 0; right < nums.length; right++) {
            if (freq[nums[right]]++ == 0) {
                inside++;
            }
            while (inside == totalDistinct) {
                answer += nums.length - right;
                if (--freq[nums[left]] == 0) {
                    inside--;
                }
                left++;
            }
        }
        return answer;
    }
}
